const sec = (heading, body, sourceIds) => ({ heading, body, sourceIds: ids(sourceIds) });
const ev = (year, title, description, sourceIds, category, placeId) => ({ year, title, description, sourceIds: ids(sourceIds), category, ...(placeId ? { placeId } : {}) });
const point = (id, name, modernName, coord, kind, polity, color, note, sourceIds, siteId) => ({ id: `mod-${id}`, name, modernName, coord, kind, polity, color, note, sourceIds: ids(sourceIds), siteId });
const city = (id, name, coord, polity, sourceIds, siteId = id) => point(id, name, name, coord, 'event', polity, C.event, '현재 도시 일대의 개략 위치다. 당시 건물이나 사건 현장의 정확한 위치를 확정한 점이 아니다.', sourceIds, siteId);
const hanseong = () => point('hanseong', '한성', '서울', [126.98, 37.57], 'capital', '조선', C.opening, '개항기 조선의 도읍. 현재 서울 도심의 개략 위치다.', ['opening'], 'seoul');
const imperialSeoul = () => point('hwangseong', '황성 한성', '서울', [126.98, 37.57], 'capital', '대한제국', C.empire, '경운궁을 중심으로 한 대한제국의 도읍. 오늘날 서울의 개략 위치다.', ['empire'], 'seoul');
const colonialSeoul = () => point('gyeongseong', '경성', '서울', [126.98, 37.57], 'event', '일제 식민통치', C.colonial, '조선총독부가 자리한 식민통치의 중심지다. 독립국의 수도로 표시하지 않는다.', ['annexation'], 'seoul');
const seoul = () => point('seoul', '서울', '서울특별시', [126.98, 37.57], 'capital', '대한민국', C.contemporary, '대한민국의 수도. 정부의 전시 피란지와 구별하며 현대 도심의 개략 위치로 표시한다.', ['government', 'seoul'], 'seoul');
const north = (year = 1948) => point('pyongyang-government', '평양', '평양', [125.75, 39.03], year < 1972 ? 'event' : 'capital', '조선민주주의인민공화국', C.north, year < 1972 ? '북쪽 정부의 실제 소재지. 1948년 헌법의 수부는 서울이었으므로 이 시기 평양에 공식 수도 표식을 붙이지 않는다.' : '평양은 1972년 헌법에서 수도로 규정되었다. 도시 일대의 개략 위치다.', year < 1972 ? ['north-constitution', 'pyongyang'] : ['north-1972', 'pyongyang'], 'pyongyang');
const eraFor = year => year < 1897 ? 'opening' : year < 1910 ? 'empire' : year < 1945 ? 'colonial' : year < 1988 ? 'contemporary' : 'recent';
const snapshot = (id, year, title, kicker, summary, places, events, sections, figureIds, polityIds, tags, note = '지도점은 당시 활동과 관련된 도시의 개략 위치다. 영토나 이동 경로를 복원한 표시는 아니다.') => ({
  id, year, era: eraFor(year), title, kicker, summary, note, color: C[eraFor(year)], places, events, sections,
  figureIds: ids(figureIds), polityIds: ids(polityIds), tags,
  sourceIds: [...new Set([...places, ...events, ...sections].flatMap(item => item.sourceIds))]
});

