const polity = (id, name, period, color, summary, sections, capitalNames) => ({ id: `mod-${id}`, name, period, color, summary, sections, capitalNames, sourceIds: [...new Set(sections.flatMap(item => item.sourceIds))] });
export const polities = [
  polity('joseon-opening', '조선 · 개항기', '1876~1897년의 조선', C.opening, '조선 왕조의 마지막 시기 가운데 개항 이후를 다루는 시대 구분이다. 별도의 새 왕조가 성립한 시기를 뜻하지 않는다.', [sec('국제 관계의 재편', '강화도 조약 이후 조선은 여러 나라와 조약을 맺고 개항장을 열었다. 열강의 경쟁 속에서 독립과 개혁의 방향이 핵심 과제가 되었다.', ['opening']), sec('서로 다른 개혁의 주체', '정부와 개화파, 농민군과 시민 단체가 각자의 방식으로 개혁을 제기했다. 1894년의 농민운동과 갑오개혁, 독립협회의 활동은 변화의 주체가 하나가 아니었음을 보여 준다.', ['donghak', 'association'])], ['한성']),
  polity('empire', '대한제국', '1897~1910', C.empire, '1897년 고종의 황제 즉위로 성립한 국가다. 황제권 중심의 개혁을 추진했으나 일본의 단계적인 침탈 끝에 주권을 잃었다.', [sec('국가와 개혁', '대한제국은 자주독립을 표방하며 광무개혁을 추진했다. 황제권 강화와 토지·재정·군사·산업 정비의 시도는 함께 살펴볼 과제다.', ['empire']), sec('국권 침탈', '1905년 외교권 박탈과 1907년 황제 강제 퇴위·군대 해산을 거쳐 일본의 지배가 강화되었다. 1910년 8월 29일 병합 공포로 대한제국은 끝났다.', ['empire', 'annexation'])], ['한성']),
  polity('colonial', '일제강점기 · 식민통치 시대', '1910~1945', C.colonial, '일본 제국주의가 한국을 식민지로 지배한 역사적 시대다. 독립 국가나 한국 왕조의 이름이 아니다.', [sec('식민통치의 구조', '조선총독부는 일본의 통치 기구였고 경성에 자리했다. 행정·군사·경찰을 통한 지배는 주민의 정치적 권리와 자율성을 제약했다.', ['annexation']), sec('다양한 독립운동', '국내외에서는 대중 시위와 임시정부, 무장투쟁과 교육·문화·사회운동이 전개되었다. 활동 방식과 사상이 달랐던 사람들의 실천을 한 가지 노선으로 축소하지 않는다.', ['march', 'products', 'singan'])], []),
  polity('provisional', '대한민국 임시정부', '1919~1945년의 국외 활동', C.contemporary, '3·1운동을 바탕으로 수립되어 독립운동을 전개한 임시정부다. 국내 영토를 지배한 정부와 국외 독립운동 정부를 구별한다.', [sec('출범과 통합', '상하이에서 1919년 4월 11일 임시헌장을 정하고 정부가 출범했다. 9월에는 각지의 임시정부 움직임을 통합하는 정부가 성립했다.', ['provisional', 'charter']), sec('이동과 군사·외교 활동', '일본의 추격과 중국의 전쟁 상황 속에서 여러 도시를 옮겨 충칭에 이르렀다. 광복군 창설과 외교 활동을 펼쳤고 해방 뒤 인사들은 개인 자격으로 귀국했다.', ['provisional', 'liberation-army'])], ['상하이 등 활동 근거지', '충칭 · 전시 활동 근거지']),
  polity('republic', '대한민국', '1948년 정부 수립 · 이 지도는 2024년까지', C.contemporary, '제헌헌법과 정부 수립 이후의 대한민국을 다룬다. 전쟁·산업화·민주화와 시민의 일상 변화가 함께 이루어진 역사다.', [sec('헌정과 전쟁', '1948년 제헌국회가 헌법을 제정하고 정부가 수립되었다. 한국전쟁 때 정부는 여러 곳으로 피란했으며 부산 임시수도와 일반 수도 서울을 구분한다.', ['government', 'busan-capital', 'return-seoul']), sec('성장과 민주주의', '정부 주도의 경제개발과 시민·노동자의 활동이 사회를 바꾸었다. 4·19혁명과 5·18민주화운동, 6월항쟁 등은 권리와 민주적 통제를 넓히려 한 과정이었다.', ['economy', 'april', 'gwangju', 'june'])], ['서울', '부산 · 한국전쟁기 임시수도']),
  polity('north', '조선민주주의인민공화국', '1948년 정부 수립 · 남북 병존', C.north, '1948년 북쪽에 수립된 정부다. 정부 출범 당시의 헌법상 수부와 실제 소재지, 이후 평양의 수도 지위를 구별한다.', [sec('정부와 소재지', '1948년 9월 9일 정부가 수립되었다. 당시 헌법은 수부를 서울로 정했지만 실제 정부는 평양에 있었으며 1972년 헌법에서 평양을 수도로 규정했다.', ['north-constitution', 'north-1972', 'pyongyang']), sec('전쟁과 남북관계', '1950년 북한군의 남침으로 한국전쟁이 시작되었고 정전 뒤 분단이 지속되었다. 1991년에는 남북이 유엔에 동시 가입했으며 이후 정상회담 등의 대화도 이루어졌다.', ['war', 'un', 'summit'])], ['평양 · 실제 정부 소재지', '서울 · 1948년 헌법상 수부'])
];
